{
  "name": "OmniNode Sovereign Control",
  "description": "A high-performance dashboard for a decentralized AI ecosystem, featuring real-time audio monitoring, neural processing visualization, and automated OS execution tracking.",
  "requestFramePermissions": [
    "microphone"
  ]
}

export type SystemStatus = 'online' | 'offline' | 'standby' | 'alert';

export interface ActionLog {
  id: string;
  timestamp: Date;
  action: string;
  status: 'success' | 'pending' | 'failed';
  details: string;
}

export interface NodeMetrics {
  cpu: number;
  memory: number;
  latency: number;
  energy: number; // Percentage from solar array
}

export enum LayerType {
  EAR = 'EAR',
  CEREBRUM = 'CEREBRUM',
  HANDS = 'HANDS',
  SECURITY = 'SECURITY'
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useEffect } from 'react';
import { Sidebar } from './components/Sidebar';
import { EarLayer } from './components/EarLayer';
import { CerebrumLayer } from './components/CerebrumLayer';
import { HandsLayer } from './components/HandsLayer';
import { SecurityLayer } from './components/SecurityLayer';
import { Header } from './components/Header';
import { LayerType } from './types';

const App: React.FC = () => {
  const [activeLayer, setActiveLayer] = useState<LayerType>(LayerType.EAR);
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);

  // Global system states
  const [metrics, setMetrics] = useState({
    cpu: 12,
    memory: 45,
    latency: 18,
    energy: 94
  });

  useEffect(() => {
    const interval = setInterval(() => {
      setMetrics(prev => ({
        cpu: Math.max(5, Math.min(95, prev.cpu + (Math.random() - 0.5) * 5)),
        memory: Math.max(20, Math.min(90, prev.memory + (Math.random() - 0.5) * 2)),
        latency: Math.max(5, Math.min(150, prev.latency + (Math.random() - 0.5) * 10)),
        energy: Math.max(0, Math.min(100, prev.energy - 0.01)) // Slowly draining
      }));
    }, 3000);
    return () => clearInterval(interval);
  }, []);

  const renderLayer = () => {
    switch (activeLayer) {
      case LayerType.EAR:
        return <EarLayer />;
      case LayerType.CEREBRUM:
        return <CerebrumLayer />;
      case LayerType.HANDS:
        return <HandsLayer />;
      case LayerType.SECURITY:
        return <SecurityLayer metrics={metrics} />;
      default:
        return <EarLayer />;
    }
  };

  return (
    <div className="flex h-screen w-full bg-[#050505] text-cyan-50/90 selection:bg-cyan-500/30">
      <div className="scanline"></div>

      <Sidebar 
        activeLayer={activeLayer} 
        setActiveLayer={setActiveLayer} 
        isOpen={isSidebarOpen}
        toggleSidebar={() => setIsSidebarOpen(!isSidebarOpen)}
      />

      <div className="flex flex-col flex-1 overflow-hidden">
        <Header metrics={metrics} />
        <main className="flex-1 relative overflow-hidden bg-[radial-gradient(circle_at_center,_rgba(34,211,238,0.03)_0%,_rgba(0,0,0,0)_100%)]">
          {renderLayer()}
        </main>
      </div>
    </div>
  );
};

export default App;

