import React, { useRef, useState, useEffect } from 'react';

export const EarLayer: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [isListening, setIsListening] = useState(false);
  const [transcription, setTranscription] = useState<string[]>([]);
  const audioContextRef = useRef<AudioContext | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const requestRef = useRef<number>();

  const startListening = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      analyserRef.current = audioContextRef.current.createAnalyser();
      const source = audioContextRef.current.createMediaStreamSource(stream);
      source.connect(analyserRef.current);
      analyserRef.current.fftSize = 256;
      setIsListening(true);

      // Simulate STT output
      const phrases = [
        "Detecting ambient signal...",
        "Identifying voice pattern...",
        "STT Pipeline (Whisper-Faster) active.",
        "Waiting for command trigger..."
      ];
      phrases.forEach((p, i) => {
        setTimeout(() => setTranscription(prev => [...prev.slice(-10), p]), i * 2000);
      });
    } catch (err) {
      console.error("Microphone access denied", err);
    }
  };

  useEffect(() => {
    const draw = () => {
      if (!canvasRef.current || !analyserRef.current) return;
      const canvas = canvasRef.current;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      const bufferLength = analyserRef.current.frequencyBinCount;
      const dataArray = new Uint8Array(bufferLength);
      analyserRef.current.getByteFrequencyData(dataArray);

      ctx.clearRect(0, 0, canvas.width, canvas.height);
      const barWidth = (canvas.width / bufferLength) * 2.5;
      let barHeight;
      let x = 0;

      for (let i = 0; i < bufferLength; i++) {
        barHeight = (dataArray[i] / 255) * canvas.height;
        ctx.fillStyle = `rgba(34, 211, 238, ${0.1 + (dataArray[i]/255)})`;
        ctx.fillRect(x, canvas.height - barHeight, barWidth, barHeight);
        x += barWidth + 2;
      }
      requestRef.current = requestAnimationFrame(draw);
    };

    if (isListening) {
      requestRef.current = requestAnimationFrame(draw);
    }
    return () => {
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, [isListening]);

  return (
    <div className="p-8 h-full flex flex-col gap-8">
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 flex-1">
        {/* Visualizer Card */}
        <div className="bg-black/40 border border-white/5 rounded-2xl p-6 flex flex-col glow-cyan relative overflow-hidden">
          <div className="flex items-center justify-between mb-8 z-10">
            <div>
              <h2 className="text-xl font-bold text-white mb-1">Mobile "Ear" Remote</h2>
              <p className="text-sm opacity-50 uppercase tracking-widest mono">Ambient Audio Stream</p>
            </div>
            <button 
              onClick={isListening ? () => setIsListening(false) : startListening}
              className={`px-6 py-2 rounded-full font-bold transition-all ${
                isListening 
                  ? 'bg-red-500/20 text-red-400 border border-red-500/50' 
                  : 'bg-cyan-500 text-black hover:bg-cyan-400'
              }`}
            >
              {isListening ? 'DISCONNECT' : 'ENGAGE EAR'}
            </button>
          </div>

          <div className="flex-1 flex items-center justify-center relative">
            {!isListening ? (
              <div className="text-center opacity-20">
                <svg className="w-24 h-24 mx-auto mb-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M19 11a7 7 0 0 1-7 7m0 0a7 7 0 0 1-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 0 1-3-3V5a3 3 0 1 1 6 0v6a3 3 0 0 1-3 3z" />
                </svg>
                <p className="mono">REMOTE SENSORY INACTIVE</p>
              </div>
            ) : (
              <canvas ref={canvasRef} width={600} height={200} className="w-full h-full max-h-[300px]" />
            )}
          </div>

          <div className="mt-8 grid grid-cols-3 gap-4">
            <div className="p-3 bg-white/5 rounded-lg border border-white/5">
              <span className="block text-[10px] opacity-40 uppercase mb-1">Codec</span>
              <span className="mono text-xs text-cyan-400">PCM-16/OPUS</span>
            </div>
            <div className="p-3 bg-white/5 rounded-lg border border-white/5">
              <span className="block text-[10px] opacity-40 uppercase mb-1">Tunnel</span>
              <span className="mono text-xs text-cyan-400">Tailscale V2</span>
            </div>
            <div className="p-3 bg-white/5 rounded-lg border border-white/5">
              <span className="block text-[10px] opacity-40 uppercase mb-1">Noise Floor</span>
              <span className="mono text-xs text-cyan-400">-42.4 dB</span>
            </div>
          </div>
        </div>

        {/* STT Log */}
        <div className="bg-black/40 border border-white/5 rounded-2xl p-6 flex flex-col relative overflow-hidden">
          <div className="flex items-center justify-between mb-6">
            <h2 className="text-lg font-bold text-white">Faster-Whisper STT</h2>
            <div className="flex gap-2">
              <span className="w-2 h-2 rounded-full bg-cyan-500 animate-pulse"></span>
              <span className="text-[10px] uppercase opacity-40 mono">Live Processing</span>
            </div>
          </div>

          <div className="flex-1 bg-black/60 rounded-xl border border-white/5 p-4 overflow-y-auto mono text-xs space-y-3 font-light leading-relaxed">
            {transcription.length === 0 && <span className="opacity-20 italic">Awaiting audio input...</span>}
            {transcription.map((text, idx) => (
              <div key={idx} className="flex gap-3">
                <span className="opacity-20 shrink-0">[{new Date().toLocaleTimeString([], { hour12: false })}]</span>
                <span className={idx === transcription.length - 1 ? "text-cyan-400" : "text-white/60"}>
                  {text}
                </span>
              </div>
            ))}
          </div>

          <div className="mt-4 flex items-center justify-between text-[10px] opacity-40 uppercase tracking-widest mono">
            <span>Server: Home-PC-Sovereign</span>
            <span>Latency: 12ms</span>
          </div>
        </div>
      </div>
    </div>
  );
};

import { GoogleGenAI, Type } from "@google/genai";

const API_KEY = process.env.API_KEY || "";

export class CerebrumService {
  private ai: GoogleGenAI;

  constructor() {
    this.ai = new GoogleGenAI({ apiKey: API_KEY });
  }

  async processCommand(input: string, history: { role: 'user' | 'model', content: string }[]) {
    try {
      const response = await this.ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: [
          ...history.map(h => ({ role: h.role === 'user' ? 'user' : 'model', parts: [{ text: h.content }] })),
          { role: 'user', parts: [{ text: input }] }
        ],
        config: {
          systemInstruction: `You are the Cerebrum, the core intelligence of a Sovereign Node.
          Your purpose is to translate user voice/text commands into actionable OS steps.
          You use a "Thinking Loop" to plan. 
          When a user gives a command, first explain your thinking/planning, then provide the logical steps to execute on the PC.

          Example:
          Thinking: User wants to start a project. I need to open VS Code and the browser.
          Plan:
          1. Check if directory 'Project-X' exists.
          2. Execute os.startfile on directory.
          3. Launch web browser to localhost:3000.`,
          thinkingConfig: { thinkingBudget: 2000 }
        }
      });
      return response.text;
    } catch (error) {
      console.error("Gemini Error:", error);
      return "Critical system error in neural processing layer. Check mesh connectivity.";
    }
  }
}

export const cerebrum = new CerebrumService();

import React, { useState, useRef, useEffect } from 'react';
import { cerebrum } from '../services/geminiService';

export const CerebrumLayer: React.FC = () => {
  const [messages, setMessages] = useState<{ role: 'user' | 'model', content: string }[]>([
    { role: 'model', content: "Sovereign Intelligence active. Logic loops ready. Command me." }
  ]);
  const [input, setInput] = useState("");
  const [isProcessing, setIsProcessing] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || isProcessing) return;

    const userMessage = input;
    setInput("");
    setMessages(prev => [...prev, { role: 'user', content: userMessage }]);
    setIsProcessing(true);

    const response = await cerebrum.processCommand(userMessage, messages);
    setMessages(prev => [...prev, { role: 'model', content: response || "Empty response from brain node." }]);
    setIsProcessing(false);
  };

  return (
    <div className="p-8 h-full flex flex-col gap-6">
      <div className="flex-1 bg-black/40 border border-white/5 rounded-2xl flex flex-col overflow-hidden relative glow-cyan">
        <div className="p-4 border-b border-white/5 flex items-center justify-between bg-black/60 backdrop-blur-md">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 rounded-full bg-cyan-500/20 flex items-center justify-center animate-pulse">
              <svg className="w-4 h-4 text-cyan-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04M12 21.355l7.117-7.117a11.955 11.955 0 01-14.234 0L12 21.355z" />
              </svg>
            </div>
            <div>
              <h2 className="text-sm font-bold text-white uppercase tracking-widest">Logic Engine</h2>
              <p className="text-[10px] opacity-40 mono uppercase">Gemini-3 Flash-Loop</p>
            </div>
          </div>
          <div className="text-[10px] mono opacity-40">
            Vector DB: Chromadb Connected | Persistence: Active
          </div>
        </div>

        <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-6">
          {messages.map((m, i) => (
            <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
              <div className={`max-w-[80%] rounded-2xl p-4 ${
                m.role === 'user' 
                  ? 'bg-cyan-500/10 border border-cyan-500/20 text-cyan-50' 
                  : 'bg-white/5 border border-white/10 text-white/80'
              }`}>
                <div className="flex items-center gap-2 mb-2 opacity-30 text-[10px] mono uppercase">
                  <span>{m.role === 'user' ? 'Operator' : 'Cerebrum'}</span>
                </div>
                <div className="whitespace-pre-wrap leading-relaxed prose prose-invert text-sm">
                  {m.content}
                </div>
              </div>
            </div>
          ))}
          {isProcessing && (
            <div className="flex justify-start">
              <div className="bg-white/5 border border-white/10 rounded-2xl p-4 flex items-center gap-3">
                <div className="flex space-x-1">
                  <div className="w-1.5 h-1.5 bg-cyan-400 rounded-full animate-bounce" style={{ animationDelay: '0ms' }}></div>
                  <div className="w-1.5 h-1.5 bg-cyan-400 rounded-full animate-bounce" style={{ animationDelay: '150ms' }}></div>
                  <div className="w-1.5 h-1.5 bg-cyan-400 rounded-full animate-bounce" style={{ animationDelay: '300ms' }}></div>
                </div>
                <span className="text-xs mono opacity-40 italic">Planning action steps...</span>
              </div>
            </div>
          )}
        </div>

        <div className="p-4 border-t border-white/5 bg-black/60">
          <div className="relative">
            <input 
              type="text"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSend()}
              placeholder="Inject command to the Logic Engine..."
              className="w-full bg-white/5 border border-white/10 rounded-xl py-3 px-5 focus:outline-none focus:border-cyan-500/50 transition-all text-sm mono"
            />
            <button 
              onClick={handleSend}
              className="absolute right-2 top-1/2 -translate-y-1/2 p-2 text-cyan-400 hover:text-cyan-300 transition-colors"
            >
              <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 5l7 7-7 7M5 5l7 7-7 7" />
              </svg>
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
