  useEffect(() => {
    // Initial dummy logs
    const initialLogs: ActionLog[] = [
      { id: '1', timestamp: new Date(Date.now() - 3600000), action: 'Launch VS Code', status: 'success', details: 'os.startfile("C:/Projects/OmniNode")' },
