import React, { useRef, useState, useEffect } from 'react';

export const EarLayer: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [isListening, setIsListening] = useState(false);
  const [transcription, setTranscription] = useState<{time: string, text: string}[]>([]);
  const audioContextRef = useRef<AudioContext | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const requestRef = useRef<number>();

  const startListening = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      analyserRef.current = audioContextRef.current.createAnalyser();
      const source = audioContextRef.current.createMediaStreamSource(stream);
      source.connect(analyserRef.current);
      analyserRef.current.fftSize = 256;
      setIsListening(true);

      const phrases = [
        "Sovereign ear online. Monitoring 16kHz stream.",
        "Local Whisper-Faster engine warming up...",
        "Ambient noise filtered. Vectorizing inputs.",
        "Listening for 'OmniNode' trigger phrase..."
      ];
      phrases.forEach((p, i) => {
        setTimeout(() => setTranscription(prev => [...prev.slice(-8), { time: new Date().toLocaleTimeString([], {hour12: false}), text: p}]), i * 1500);
      });
    } catch (err) {
      console.error("Microphone access denied", err);
    }
  };

  useEffect(() => {
    const draw = () => {
      if (!canvasRef.current || !analyserRef.current) return;
      const canvas = canvasRef.current;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      const bufferLength = analyserRef.current.frequencyBinCount;
      const dataArray = new Uint8Array(bufferLength);
      analyserRef.current.getByteFrequencyData(dataArray);

      ctx.clearRect(0, 0, canvas.width, canvas.height);
      const barWidth = (canvas.width / bufferLength) * 2;
      let x = 0;

      for (let i = 0; i < bufferLength; i++) {
        const barHeight = (dataArray[i] / 255) * canvas.height;
        const g = ctx.createLinearGradient(0, canvas.height, 0, canvas.height - barHeight);
        g.addColorStop(0, 'rgba(34, 211, 238, 0.1)');
        g.addColorStop(1, 'rgba(34, 211, 238, 0.8)');
        ctx.fillStyle = g;
        ctx.fillRect(x, canvas.height - barHeight, barWidth, barHeight);
        x += barWidth + 1;
      }
      requestRef.current = requestAnimationFrame(draw);
    };

    if (isListening) {
      requestRef.current = requestAnimationFrame(draw);
    }
    return () => {
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
    };
  }, [isListening]);

  return (
    <div className="p-8 h-full flex flex-col gap-6 animate-in fade-in duration-500">
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 flex-1">
        {/* Visualizer Card */}
        <div className="bg-black/40 border border-white/5 rounded-2xl p-6 flex flex-col glow-cyan relative overflow-hidden group">
          <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-30 transition-opacity">
            <svg className="w-32 h-32" viewBox="0 0 24 24" fill="none" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={0.5} d="M15.536 8.464a5 5 0 010 7.072m2.828-9.9a9 9 0 010 12.728M5.586 15H4a1 1 0 01-1-1v-4a1 1 0 011-1h1.586l4.707-4.707C10.923 3.663 12 4.109 12 5v14c0 .891-1.077 1.337-1.707.707L5.586 15z" />
            </svg>
