import React, { useState, useRef, useEffect } from 'react';
import { cerebrum } from '../services/geminiService';
import { ConnectionMode, MemoryVector } from '../types';

interface Props {
  connectionMode: ConnectionMode;
  setConnectionMode: (mode: ConnectionMode) => void;
}

export const CerebrumLayer: React.FC<Props> = ({ connectionMode, setConnectionMode }) => {
  const [messages, setMessages] = useState<{ role: 'user' | 'model', content: string }[]>(() => {
    const saved = localStorage.getItem('cerebrum_history');
    return saved ? JSON.parse(saved) : [{ role: 'model', content: "Sovereign Intelligence active. Local Mesh logic loops ready." }];
  });
  const [memory, setMemory] = useState<MemoryVector[]>([
    { id: '1', key: 'User Preferences', snippet: 'Prefers dark theme, Python over Node', timestamp: '2h ago' },
    { id: '2', key: 'Last Command', snippet: 'Initiated tailscale up --local-only', timestamp: '1h ago' },
    { id: '3', key: 'Context Path', snippet: 'Active dir: C:/Users/OmniNode/Sovereign', timestamp: '30m ago' },
  ]);
  const [input, setInput] = useState("");
  const [isProcessing, setIsProcessing] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    localStorage.setItem('cerebrum_history', JSON.stringify(messages));
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || isProcessing) return;

    const userMessage = input;
    setInput("");
    setMessages(prev => [...prev, { role: 'user', content: userMessage }]);
    setIsProcessing(true);

    if (connectionMode === 'local-mesh') {
      setTimeout(() => {
        setMessages(prev => [...prev, { 
          role: 'model', 
          content: `[OLLAMA_LLM_RESPONSE @ 127.0.0.1:11434]\n\nThinking: Querying ChromaDB for context... found "User Preferences".\n\nPlan:\n1. Open Terminal and execute local automation script.\n2. Log status to Sovereign Hub.\n\nCommand executed successfully in local isolation.` 
        }]);
        setMemory(prev => [{ id: Date.now().toString(), key: 'New Command', snippet: userMessage.substring(0, 30) + '...', timestamp: 'just now' }, ...prev.slice(0, 5)]);
        setIsProcessing(false);
      }, 1000);
    } else {
      const response = await cerebrum.processCommand(userMessage, messages);
      setMessages(prev => [...prev, { role: 'model', content: response || "Empty response from brain node." }]);
      setIsProcessing(false);
    }
  };

  return (
    <div className="p-8 h-full flex flex-col gap-6 animate-in slide-in-from-bottom-4 duration-500">
      <div className="grid grid-cols-1 xl:grid-cols-4 gap-6 flex-1 min-h-0">

        {/* Memory Panel (Vector DB) */}
        <div className="xl:col-span-1 bg-black/40 border border-white/5 rounded-2xl p-6 flex flex-col gap-4">
          <div className="flex items-center gap-3 border-b border-white/5 pb-4">
            <svg className="w-5 h-5 text-amber-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" />
            </svg>
            <h3 className="text-sm font-bold uppercase tracking-widest text-white/70">Vector Memory</h3>
          </div>
          <div className="flex-1 overflow-y-auto space-y-3 pr-2 custom-scrollbar">
            {memory.map(v => (
              <div key={v.id} className="p-3 bg-white/5 border border-white/5 rounded-xl hover:border-amber-500/30 transition-all cursor-help group">
                <div className="flex justify-between items-center mb-1">
                  <span className="text-[10px] font-bold text-amber-400/80 uppercase">{v.key}</span>
                  <span className="text-[8px] opacity-20 mono">{v.timestamp}</span>
                </div>
                <p className="text-[10px] text-white/50 leading-relaxed font-light">{v.snippet}</p>
              </div>
            ))}
          </div>
          <div className="pt-4 border-t border-white/5 text-[9px] mono opacity-30 uppercase flex justify-between">
            <span>DB: ChromaDB</span>
            <span>Count: 142 Vectors</span>
          </div>
        </div>

        {/* Chat / Logic Panel */}
        <div className="xl:col-span-3 bg-black/40 border border-white/5 rounded-2xl flex flex-col overflow-hidden relative glow-cyan">
          <div className="p-4 border-b border-white/5 flex items-center justify-between bg-black/60 backdrop-blur-md z-10">
            <div className="flex items-center gap-3">
              <div className={`w-8 h-8 rounded-full flex items-center justify-center animate-pulse ${connectionMode === 'local-mesh' ? 'bg-green-500/20' : 'bg-cyan-500/20'}`}>
                <div className={`w-2 h-2 rounded-full ${connectionMode === 'local-mesh' ? 'bg-green-400' : 'bg-cyan-400'}`}></div>
              </div>
              <div>
                <h2 className="text-xs font-bold text-white uppercase tracking-[0.2em]">Neural Cerebrum</h2>
                <p className="text-[10px] opacity-40 mono uppercase">
                  {connectionMode === 'local-mesh' ? 'OFFLINE Llama-3 Node' : 'CLOUD BRIDGE ACTIVE'}
                </p>
              </div>
            </div>

            <div className="flex gap-2">
              <ModeButton 
                active={connectionMode === 'local-mesh'} 
                onClick={() => setConnectionMode('local-mesh')} 
                label="LOCAL MESH" 
                color="green" 
              />
              <ModeButton 
                active={connectionMode === 'cloud-bridge'} 
                onClick={() => setConnectionMode('cloud-bridge')} 
                label="CLOUD BRIDGE" 
                color="cyan" 
              />
            </div>
          </div>

          <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-6 custom-scrollbar bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')]">
            {messages.map((m, i) => (
              <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div className={`max-w-[85%] rounded-2xl p-4 shadow-2xl ${
                  m.role === 'user' 
                    ? 'bg-cyan-500/10 border border-cyan-500/30 text-cyan-50 backdrop-blur-sm' 
                    : 'bg-black/60 border border-white/10 text-white/80 backdrop-blur-md'
                }`}>
                  <div className="flex items-center gap-2 mb-2 opacity-30 text-[9px] mono uppercase font-bold tracking-widest">
                    <span>{m.role === 'user' ? 'OPERATOR_IN' : 'BRAIN_OUT'}</span>
                  </div>
                  <div className="whitespace-pre-wrap leading-relaxed text-sm font-light">
                    {m.content}
                  </div>
                </div>
              </div>
            ))}
            {isProcessing && (
              <div className="flex justify-start">
                <div className="bg-white/5 border border-white/10 rounded-2xl p-4 flex items-center gap-4">
                  <div className="flex space-x-1.5">
                    <div className="w-1.5 h-1.5 bg-cyan-400 rounded-full animate-bounce" style={{ animationDelay: '0ms' }}></div>
                    <div className="w-1.5 h-1.5 bg-cyan-400 rounded-full animate-bounce" style={{ animationDelay: '150ms' }}></div>
                    <div className="w-1.5 h-1.5 bg-cyan-400 rounded-full animate-bounce" style={{ animationDelay: '300ms' }}></div>
                  </div>
                  <span className="text-[10px] mono opacity-40 italic uppercase tracking-widest">Synthesizing Logic Gates...</span>
                </div>
              </div>
            )}
          </div>

          <div className="p-4 border-t border-white/5 bg-black/80 backdrop-blur-xl">
            <div className="relative group">
              <div className="absolute -inset-1 bg-gradient-to-r from-cyan-500 to-blue-600 rounded-xl blur opacity-10 group-focus-within:opacity-30 transition duration-1000"></div>
              <input 
                type="text"
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                placeholder={connectionMode === 'local-mesh' ? "Direct command to Llama-3 (Port 11434)..." : "Relay command through Gemini Cloud..."}
                className="relative w-full bg-black border border-white/10 rounded-xl py-4 px-6 focus:outline-none focus:border-cyan-500/50 transition-all text-sm mono text-cyan-50/80 placeholder:opacity-30"
              />
              <div className="absolute right-4 top-1/2 -translate-y-1/2 text-[9px] mono opacity-20 uppercase tracking-widest pointer-events-none">
                Press Enter
              </div>
            </div>
          </div>
        </div>

      </div>
    </div>
  );
};

const ModeButton: React.FC<{ active: boolean, onClick: () => void, label: string, color: string }> = ({ active, onClick, label, color }) => (
  <button 
    onClick={onClick}
    className={`px-4 py-1.5 rounded-lg text-[9px] font-bold mono border transition-all tracking-[0.1em] ${
      active 
